  /// timeline ms (token_timestamps only, else -1)
  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;
}

final class vv_stt_segment extends ffi.Struct {
  /// 0.. within the job
  @ffi.Int32()
